def compute(vars):
    amortizable_loss = vars["v1"]
    net_deferred_loss = vars["v2"]

    if net_deferred_loss == 0:
        return None

    percentage = amortizable_loss / net_deferred_loss * 100
    return {
        "value": percentage,
        "trace": {
            "amortizable_loss": amortizable_loss,
            "net_deferred_loss": net_deferred_loss,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
